const products=[['Сукня «Квіткова мрія»','clothes','₴ 690','👗'],['Светрик «Обіймашка»','clothes','₴ 520','🧶'],['Штанці «Хмаринка»','clothes','₴ 430','👖'],['Піжама «Зірочки»','clothes','₴ 590','🌙'],['Кеди «Туп-туп»','shoes','₴ 780','👟'],['Черевички «Тепло»','shoes','₴ 890','🥾'],['Ведмедик Тедді','toys','₴ 390','🧸'],['Конструктор «Веселка»','toys','₴ 620','🧱'],['Пазл «Мій Київ»','toys','₴ 280','🧩'],['Набір фарб','toys','₴ 340','🎨'],['М’яка ковдрочка','baby','₴ 750','🧺'],['Прорізувач «Листочок»','baby','₴ 210','🍃']];let cart=[];const $=s=>document.querySelector(s);function render(filter='all'){let p=products.filter(x=>filter==='all'||x[1]===filter);let sort=$('#sort').value;if(sort==='cheap')p.sort((a,b)=>+a[2].replace(/\D/g,'')-+b[2].replace(/\D/g,''));if(sort==='expensive')p.sort((a,b)=>+b[2].replace(/\D/g,'')-+a[2].replace(/\D/g,''));$('#products').innerHTML=p.map((x,i)=>`<article class="card"><button class="heart">♡</button><div class="pic">${x[3]}</div><h3>${x[0]} <button class="add" data-name="${x[0]}">+</button></h3><span class="muted">${x[1]==='toys'?'для гри та фантазії':'м’які матеріали'}</span><div class="price">${x[2]}</div></article>`).join('');document.querySelectorAll('.add').forEach(b=>b.onclick=()=>{let x=products.find(p=>p[0]===b.dataset.name);cart.push(x);updateCart();openDrawer()})}function updateCart(){$('#cartCount').textContent=cart.length;$('#cartItems').innerHTML=cart.length?cart.map((x,i)=>`<div class="cart-row"><div class="mini">${x[3]}</div><div><h4>${x[0]}</h4><span>${x[2]}</span></div><button class="remove" data-i="${i}">×</button></div>`).join(''):'<p class="muted">Кошик ще порожній — додайте щось миле ♡</p>';document.querySelectorAll('.remove').forEach(b=>b.onclick=()=>{cart.splice(+b.dataset.i,1);updateCart()});$('#total').textContent='₴ '+cart.reduce((s,x)=>s+ +x[2].replace(/\D/g,''),0)}function openDrawer(){$('#drawer').classList.add('open');$('#shade').classList.add('show')}function closeDrawer(){$('#drawer').classList.remove('open');$('#shade').classList.remove('show')}document.querySelectorAll('.cat').forEach(b=>b.onclick=()=>{document.querySelectorAll('.cat').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.cat)});$('#sort').onchange=()=>render(document.querySelector('.cat.active').dataset.cat);$('#openCart').onclick=openDrawer;$('#closeCart').onclick=closeDrawer;$('#shade').onclick=closeDrawer;$('#checkout').onclick=()=>{$('#modal').classList.add('show');closeDrawer()};$('#closeModal').onclick=()=>$('#modal').classList.remove('show');$('#send').onclick=()=>{alert('Дякуємо! У демо-версії замовлення не надсилається.');$('#modal').classList.remove('show')};render();updateCart();

